import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    d = int(data[0])
    dead = set(data[1:1 + d])
    target = data[1 + d]
    if '0000' in dead or target in dead:
        print(-1)
        return
    if target == '0000':
        print(0)
        return
    dist = {'0000': 0}
    dq = deque(['0000'])
    while dq:
        s = dq.popleft()
        for i in range(4):
            v = int(s[i])
            for nv in ((v + 1) % 10, (v - 1) % 10):
                t = s[:i] + str(nv) + s[i + 1:]
                if t not in dist and t not in dead:
                    dist[t] = dist[s] + 1
                    if t == target:
                        print(dist[t])
                        return
                    dq.append(t)
    print(-1)

